    try {
      deadlineTriggered = true;
      ensureCancelRequest(paths, spec.runId, 'absolute_deadline_exceeded', now());
      if (!abort.signal.aborted) abort.abort(new Error('absolute_deadline_exceeded'));
    } catch (error) {
      failSupervisor(error);
    }
